import {
    Object3D,
    Mesh,
    PlaneGeometry,
    DoubleSide,
    SRGBColorSpace,
    Texture,
    Vector3,
    Euler
} from 'three/webgpu';
import {
    nodeMaterial,
    texture as texNode,
    uv,
    mul,
    float,
    add,
    positionWorld,
    cameraPosition,
    vec3
} from 'three/tsl';
import { gsap } from 'gsap';
import { primitives as primitiveCatalog } from '@/primitives';
import { fontAtlas as _unusedFontAtlas } from '@/text'; // placeholder to satisfy import rule

export default function createNode(config, ctx) {
    // Geometry
    const geometry = new PlaneGeometry(1, 1, 64, 64);

    // Load textures (synchronous via cached loaders)
    const colorMap = ctx.textureLoader.load(config.assets?.imageUrl ?? '');
    const depthMap = ctx.textureLoader.load(config.assets?.depthMapUrl ?? '');

    // Ensure correct encoding
    if (colorMap) colorMap.colorSpace = SRGBColorSpace;
    if (depthMap) depthMap.colorSpace = SRGBColorSpace;

    // Node based material
    const colorNode = texNode(colorMap, uv());
    // Displace using depth map's red channel, scale to subtle depth (0.15 scene units)
    const displacementScale = float(0.15);
    const displacementNode = mul(texNode(depthMap, uv()).r, displacementScale);

    const material = nodeMaterial({
        color: colorNode,
        displacement: displacementNode,
        side: DoubleSide
    });

    // Mesh
    const plane = new Mesh(geometry, material);
    plane.castShadow = false;
    plane.receiveShadow = false;

    // Apply config transforms
    const pos = config.position ?? [0, 0, 0];
    const rot = config.rotation ?? [0, 0, 0];
    const scl = config.scale ?? [1, 1, 1];
    plane.position.set(pos[0], pos[1], pos[2]);
    plane.rotation.set(rot[0], rot[1], rot[2]);
    plane.scale.set(scl[0], scl[1], scl[2]);

    // Store original Y for hover animation
    const originalY = plane.position.y;

    // GSAP tweens container for cleanup
    const activeTweens = [];

    // Interaction handlers
    plane.userData.handlers = {};

    // Hover (rise‑in)
    plane.userData.handlers.hover = (enter) => {
        // Cancel any existing hover tween
        activeTweens.forEach(t => t.kill());
        activeTweens.length = 0;

        const targetY = enter ? originalY + 0.15 : originalY;
        const tween = gsap.to(plane.position, {
            y: targetY,
            duration: 0.7,
            ease: 'power3.out'
        });
        activeTweens.push(tween);
    };

    // Click (emit & navigate, press‑down)
    plane.userData.handlers.click = () => {
        // Press‑down animation
        const press = gsap.to(plane.scale, {
            x: 0.97,
            y: 0.97,
            z: 0.97,
            duration: 0.12,
            ease: 'back.out(1.7)'
        });
        const release = gsap.to(plane.scale, {
            x: 1,
            y: 1,
            z: 1,
            delay: 0.12,
            duration: 0.2,
            ease: 'back.out(1.7)'
        });
        activeTweens.push(press, release);

        // Emit selection event if an emitter is provided
        if (typeof ctx.emit === 'function') {
            ctx.emit('hub-features.select');
        }

        // Navigate to checkout URL if bound
        const checkoutBinding = (config.dataBindings || []).find(
            (b) => b.source === 'trpc.checkout.begin.checkoutUrl'
        );
        if (checkoutBinding && plane.userData.checkoutUrl) {
            window.open(plane.userData.checkoutUrl, '_blank');
        }
    };

    // Store data bindings for external system
    plane.userData.bindings = config.dataBindings || [];

    // Apply cinematic primitives listed in config
    (config.cinematicPrimitives || []).forEach((prim) => {
        if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
            ctx.primitives[prim.name](plane, prim.params);
        }
    });

    // Ensure subtle parallax effect via built‑in primitive if not already applied
    if (ctx.primitives && typeof ctx.primitives['parallax-scroll'] === 'function') {
        ctx.primitives['parallax-scroll'](plane, {});
    }

    // Cleanup function
    plane.userData.cleanup = () => {
        // Kill all tweens
        activeTweens.forEach((t) => t.kill());
        activeTweens.length = 0;

        // Dispose resources
        if (colorMap) (colorMap as Texture).dispose();
        if (depthMap) (depthMap as Texture).dispose();
        geometry.dispose();
        material.dispose();
    };

    // Return the assembled object
    return plane;
}
